// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    // Fuzzed parameters: amount to send and whether the adversary should revert when receiving
    function testFuzz_property(uint256 amount, bool shouldRevert) public {
        // keep amount in a reasonable range so the test runner can fund accounts
        amount = bound(amount, 0, 1 ether);

        // deploy a helper that can either accept or revert in its fallback/receive
        Adversary adv = new Adversary(shouldRevert);

        // fund the contract so it has ETH to send
        vm.deal(address(c), 1 ether);

        // Call sendMoney and observe whether it reverts via try/catch
        bool ok;
        try c.sendMoney(address(adv), amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: on the reference C, sendMoney never reverts for any target/amount - it ignores call failures.
        // The mutant that uses transfer will revert when the callee rejects receiving ETH (shouldRevert==true && amount>0).
        assertTrue(ok);
    }
}

// Adversarial helper: when shouldRevert is true it reverts on receive/fallback; otherwise it accepts and records calls
contract Adversary {
    bool public shouldRevert;
    uint public receivedCalls;
    uint public totalValue;

    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }

    // accept or revert on plain transfers/calls with empty calldata
    receive() external payable {
        if (shouldRevert) revert("reject");
        receivedCalls += 1;
        totalValue += msg.value;
    }

    fallback() external payable {
        if (shouldRevert) revert("reject");
        receivedCalls += 1;
        totalValue += msg.value;
    }
}
